import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Usage test.'});
const session = (): ChatSession => ({
  sessionId: 's',
  userId: 'u',
  entries: [{role: 'user', content: 'use tool', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

describe('ChatOrchestrator usage aggregation', () => {
  it('sums usage across multiple rounds', async () => {
    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register(
      {name: 'tool', description: 'desc', inputSchema: {type: 'object'}},
      async () => 'result'
    );

    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        if (round === 0) {
          round++;
          yield {type: 'tool_use', toolCall: {id: '1', name: 'tool', input: {}}};
          yield usageStop('tool_use', {inputTokens: 10, outputTokens: 5, totalTokens: 15});
        } else {
          yield {type: 'text', text: 'done'};
          yield usageStop('end_turn', {inputTokens: 20, outputTokens: 10, totalTokens: 30});
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(session());

    expect(reportedUsage).toEqual({
      inputTokens: 30,
      outputTokens: 15,
      totalTokens: 45,
    });
  });
});

